function cdqPdfDriveUrlV2271(id){
  return 'https://drive.google.com/file/d/'+encodeURIComponent(String(id||''))+'/view?usp=drivesdk';
}

function cdqPdfIntentV2271(id,packageName){
  const fileId=encodeURIComponent(String(id||''));
  const driveUrl=cdqPdfDriveUrlV2271(id);
  let intent='intent://drive.google.com/file/d/'+fileId+'/view#Intent;scheme=https;action=android.intent.action.VIEW;type=application/pdf;';
  if(packageName)intent+='package='+packageName+';';
  intent+='S.browser_fallback_url='+encodeURIComponent(driveUrl)+';end';
  return intent;
}

function cdqMarquerPdfOuvertV2271(id){
  if(String(utilisateurCourantRole||'')==='lecture')return;
  try{
    fichierOuvertPourModification=id;
    const meta=cdqDocumentMeta(id)||{};
    sessionStorage.setItem('fichierEnModification',id);
    sessionStorage.setItem('ancienneDateModification',String(meta.dateModification||''));
    sessionStorage.setItem('momentModification',String(Date.now()));
  }catch(_){}
}

function cdqOuvrirPdfAndroidV2271(id){
  const pref=cdqPdfReaderPreference();
  cdqMarquerPdfOuvertV2271(id);

  if(pref==='cdq'){
    return cdqOpenPdf(id).catch(afficherErreur);
  }

  let target;
  if(pref==='ilovepdf'){
    target=cdqPdfIntentV2271(id,'com.ilovepdf.www');
  }else if(pref==='acrobat'){
    target=cdqPdfIntentV2271(id,'com.adobe.reader');
  }else{
    target=cdqPdfIntentV2271(id,'');
  }

  const opened=window.open(target,'_blank','noopener');
  if(!opened){
    try{window.location.href=target;}catch(_){
      window.open(cdqPdfDriveUrlV2271(id),'_blank','noopener');
    }
  }
  return true;
}

const cdqV19OldModify=window.modifierFichier;
window.modifierFichier=function(id){
  const meta=cdqDocumentMeta(id);

  if(meta&&meta.type==='GOOGLE_SHEETS'){
    cdqV19OpenOfflineSheet(id);
    return;
  }

  if(meta&&meta.type==='PDF'){
    if(navigator.onLine!==false){
      if(/Android/i.test(navigator.userAgent||'')){
        return cdqOuvrirPdfAndroidV2271(id);
      }
      return cdqV19OldModify(id);
    }
    return cdqOpenPdf(id).catch(afficherErreur);
  }

  if(!navigator.onLine){
    afficherMessage('Ouvrez ce fichier dans son application après l’avoir enregistré sur le téléphone.',false);
    return;
  }
  return cdqV19OldModify(id);
};

